def store(d, key, value):
    try:
        d[key] = value
        print("stored", key)
    except TypeError:
        print("cannot use", key)
    finally:
        print("done")

d = {}
store(d, (1, 2), "a")
store(d, [3, 4], "b")
print(len(d))

def load(x):
    try:
        return 10 // x
    except Exception:
        print("general")
        return -1
    except ZeroDivisionError:
        print("zero")
        return 0
    finally:
        print("cleanup")

print(load(5))
print(load(0))

